ALTER TYPE operation_job_status ADD VALUE IF NOT EXISTS 'dead_letter';
CREATE TABLE operation_job_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operation_job_id UUID NOT NULL REFERENCES operation_jobs(id) ON DELETE CASCADE, event_type TEXT NOT NULL, progress SMALLINT CHECK (progress BETWEEN 0 AND 100), message TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX operation_job_events_timeline_idx ON operation_job_events(operation_job_id,created_at,id);
CREATE TABLE operation_output_manifests (operation_job_id UUID PRIMARY KEY REFERENCES operation_jobs(id) ON DELETE CASCADE, storage_key TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes>=0), checksum_sha256 TEXT NOT NULL CHECK(checksum_sha256 ~ '^[a-f0-9]{64}$'), metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notification_preferences (organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, channel TEXT NOT NULL CHECK(channel IN('in_app','email','push')), destination TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,user_id,channel));
CREATE TABLE provider_reconciliations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, provider TEXT NOT NULL, resource_type TEXT NOT NULL, external_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('matched','drifted','missing','error')), expected JSONB NOT NULL DEFAULT '{}', observed JSONB NOT NULL DEFAULT '{}', checked_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX provider_reconciliations_org_idx ON provider_reconciliations(organization_id,checked_at DESC);
